package main

import "fmt"

func main() {
    // Example of a simple filename validation
    filenames := []string{"peters_mixtape.mp3", "../etc/passwd", "song.wav"}
    for _, filename := range filenames {
        if isValidFilename(filename) {
            fmt.Println(filename, "is valid.")
        } else {
            fmt.Println(filename, "is invalid.")
        }
    }
}

func isValidFilename(filename string) bool {
    // Check for path traversal by ensuring the filename does not contain any path separators
    return !strings.ContainsAny(filename, "/\\")
}
